import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [compareIds, setCompareIds] = useState([]);
  const [loading, setLoading] = useState(true);
  
  const [printingId, setPrintingId] = useState(null);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [activeReviewTd, setActiveReviewTd] = useState(null);
  const [hoverRating, setHoverRating] = useState(null);
  
  // Состояния для отдельной модалки комментариев
  const [showCommentModal, setShowCommentModal] = useState(false);
  const [activeComment, setActiveComment] = useState('');
  const [commentModalTitle, setCommentModalTitle] = useState('Комментарий менеджера');
  
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateStatus, setUpdateStatus] = useState(null);

  const [reviewForm, setReviewForm] = useState({
    test_drive_id: null,
    rating: 5,
    comment: ''
  });

  const tabs = [
    { key: 'profile', label: 'Профиль' },
    { key: 'purchases', label: 'История покупок' },
    { key: 'testdrives', label: 'Тест-драйвы' },
    { key: 'loans', label: 'Кредитные заявки' },
    { key: 'favorites', label: 'Избранное' },
    { key: 'compare', label: 'Сравнение авто' },
    { key: 'notifications', label: 'Уведомления' }
  ];

  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      const [pRes, tRes, lRes] = await Promise.all([
        api.get('/purchases/my'),
        api.get('/testdrives/my'),
        api.get('/loans/my'),
      ]);
      setPurchases(pRes.data);
      setTestDrives(tRes.data);
      setLoans(lRes.data);

      const cachedFavs = JSON.parse(localStorage.getItem('favorites') || '[]');
      setFavorites(cachedFavs);

      const cachedCompareIds = JSON.parse(localStorage.getItem('compareIds') || '[]');
      setCompareIds(cachedCompareIds);
    } catch (err) {
      console.error('Ошибка при загрузке данных ЛК:', err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setUpdateStatus(null);
    try {
      const res = await api.put('/users/me', profileForm);
      setUser(res.data);
      setUpdateStatus({ type: 'success', text: 'Профиль успешно обновлен' });
    } catch (err) {
      setUpdateStatus({ type: 'error', text: 'Ошибка при обновлении профиля' });
    }
  };

  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/reviews', {
        test_drive_id: activeReviewTd.id,
        rating: reviewForm.rating,
        comment: reviewForm.comment
      });
      setShowReviewModal(false);
      setReviewForm({ test_drive_id: null, rating: 5, comment: '' });
      fetchData();
    } catch (err) {
      console.error('Ошибка при отправке отзыва:', err);
    }
  };

  const handlePrintReceipt = (purchaseId) => {
    setPrintingId(purchaseId);
    setTimeout(() => {
      window.print();
      setPrintingId(null);
    }, 300);
  };

  const removeFavorite = (carId) => {
    const updated = favorites.filter(car => car.id !== carId);
    setFavorites(updated);
    localStorage.setItem('favorites', JSON.stringify(updated));
  };

  const removeCompare = (carId) => {
    const updated = compareIds.filter(id => id !== carId);
    setCompareIds(updated);
    localStorage.setItem('compareIds', JSON.stringify(updated));
  };

  const renderTabContent = () => {
    if (loading) return <div className={styles.loading}>Загрузка данных...</div>;

    switch (activeTab) {
      case 'profile':
        return (
          <div className={styles.profileSection}>
            <h3>Личные данные</h3>
            <form onSubmit={handleProfileSubmit} className={styles.profileForm}>
              <div className={styles.field}>
                <label>ФИО</label>
                <input 
                  type="text" 
                  value={profileForm.full_name} 
                  onChange={(e) => setProfileForm({ ...profileForm, full_name: e.target.value })} 
                  required 
                />
              </div>
              <div className={styles.field}>
                <label>Телефон</label>
                <input 
                  type="text" 
                  value={profileForm.phone} 
                  onChange={(e) => setProfileForm({ ...profileForm, phone: e.target.value })} 
                  required 
                />
              </div>
              <div className={styles.field}>
                <label>Email (не редактируется)</label>
                <input type="email" value={user?.email || ''} disabled />
              </div>
              {updateStatus && (
                <p className={updateStatus.type === 'success' ? styles.successText : styles.errorText}>
                  {updateStatus.text}
                </p>
              )}
              <button type="submit" className={styles.saveBtn}>Сохранить изменения</button>
            </form>
          </div>
        );

      case 'purchases':
        return purchases.length ? (
          <div className={styles.cardsGrid}>
            {purchases.map((p) => (
              <div key={p.id} className={`${styles.card} ${printingId === p.id ? styles.receiptCard : ''}`}>
                {printingId === p.id ? (
                  <div className={styles.receiptHeader}>
                    <h4>Luxury Dealer Receipt</h4>
                    <span>ID: {p.id}</span>
                  </div>
                ) : (
                  <div className={styles.cardHeader}>Покупка #{p.id}</div>
                )}
                <div className={styles.cardBody}>
                  <p>Автомобиль: <strong>{p.car?.brand} {p.car?.model} ({p.car?.year})</strong></p>
                  <p className={styles.price}>Цена: {p.price?.toLocaleString()} ₽</p>
                  <p>Способ оплаты: {p.payment_method === 'credit' ? 'Кредит' : 'Карта / Наличные'}</p>
                  <p>Дата: {new Date(p.created_at).toLocaleDateString()}</p>
                  {!printingId && (
                    <button className={styles.viewCommentBtn} onClick={() => handlePrintReceipt(p.id)}>
                      🖨️ Печать чека
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас пока нет оформленных покупок автомобилей.</p>
        );

      case 'testdrives':
        return testDrives.length ? (
          <div className={styles.cardsGrid}>
            {testDrives.map((td) => (
              <div key={td.id} className={styles.card}>
                <div className={styles.cardHeader}>Тест-драйв #{td.id}</div>
                <div className={styles.cardBody}>
                  <p>Автомобиль: <strong>{td.car?.brand} {td.car?.model}</strong></p>
                  <p>Дата и время: {new Date(td.date_time).toLocaleString()}</p>
                  <p>Статус: <strong>{td.status}</strong></p>
                  {td.status === 'completed' && !td.has_review && (
                    <button 
                      className={styles.viewCommentBtn} 
                      onClick={() => { setActiveReviewTd(td); setShowReviewModal(true); }}
                    >
                      ⭐ Оставить отзыв
                    </button>
                  )}
                  {td.comment && (
                    <button 
                      className={styles.viewCommentBtn}
                      onClick={() => {
                        setActiveComment(td.comment);
                        setCommentModalTitle(`Ответ по тест-драйву #${td.id}`);
                        setShowCommentModal(true);
                      }}
                    >
                      💬 Посмотреть примечание
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас нет запланированных тест-драйвов.</p>
        );

      case 'loans':
        return loans.length ? (
          <div className={styles.cardsGrid}>
            {loans.map((loan) => (
              <div key={loan.id} className={styles.card}>
                <div className={styles.cardHeader}>Кредитная заявка #{loan.id}</div>
                <div className={styles.cardBody}>
                  <p>Автомобиль: <strong>{loan.car?.brand} {loan.car?.model}</strong></p>
                  <p>Сумма кредита: {loan.amount?.toLocaleString()} ₽</p>
                  <p>Срок: {loan.term_months} мес.</p>
                  <p>Ставка: {loan.interest_rate}%</p>
                  <p>Статус: <strong>{loan.status || 'На рассмотрении'}</strong></p>
                  {loan.comment && (
                    <button 
                      className={styles.viewCommentBtn}
                      onClick={() => {
                        setActiveComment(loan.comment);
                        setCommentModalTitle(`Комментарий к кредиту на ${loan.car?.brand} ${loan.car?.model}`);
                        setShowCommentModal(true);
                      }}
                    >
                      💬 Посмотреть ответ
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас нет активных кредитных заявок.</p>
        );

      case 'favorites':
        return favorites.length ? (
          <div className={styles.favoritesGrid}>
            {favorites.map((car) => (
              <div key={car.id} className={styles.favCard}>
                <img src={getImageUrl(car.image_url || car.images?.[0])} alt={car.model} className={styles.favImage} />
                <div className={styles.favInfo}>
                  <h4>{car.brand} {car.model}</h4>
                  <p className={styles.price}>{car.price?.toLocaleString()} ₽</p>
                  <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.5rem' }}>
                    <Link to={`/cars/${car.id}`} className={styles.viewCarLink}>Перейти</Link>
                    <button className={styles.removeCarBtn} onClick={() => removeFavorite(car.id)}>Удалить</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Список избранного пуст.</p>
        );

      case 'compare':
        return compareIds.length ? (
          <div className={styles.cardsGrid}>
            {compareIds.map((id) => (
              <div key={id} className={styles.card}>
                <div className={styles.cardHeader}>ID авто в сравнении: {id}</div>
                <div className={styles.cardBody}>
                  <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.5rem' }}>
                    <Link to={`/cars/${id}`} className={styles.viewCarLink}>Посмотреть</Link>
                    <button className={styles.removeCarBtn} onClick={() => removeCompare(id)}>Убрать</button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>Нет автомобилей для сравнения.</p>
        );

      case 'notifications':
        return notifications && notifications.length ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <button className={styles.clearBtn} onClick={clearNotifications}>Очистить все</button>
            {notifications.map((n, idx) => (
              <div key={idx} className={styles.card}>
                <p>{n.message || n}</p>
                <small>{n.date ? new Date(n.date).toLocaleString() : ''}</small>
              </div>
            ))}
          </div>
        ) : (
          <p className={styles.empty}>У вас нет новых уведомлений.</p>
        );

      default:
        return null;
    }
  };

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 className={styles.title}>Личный кабинет</h2>
      <div className={styles.tabs}>
        {tabs.map((tab) => (
          <button
            key={tab.key}
            className={`${styles.tab} ${activeTab === tab.key ? styles.active : ''}`}
            onClick={() => setActiveTab(tab.key)}
          >
            {tab.label}
          </button>
        ))}
      </div>

      <div className={styles.tabContent}>
        {renderTabContent()}
      </div>

      {/* Модальное окно отзыва */}
      <AnimatePresence>
        {showReviewModal && (
          <motion.div 
            className={styles.modalOverlay} 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            onClick={() => { setShowReviewModal(false); setActiveReviewTd(null); }}
          >
            <motion.div 
              className={styles.modalCard} 
              initial={{ scale: 0.9, opacity: 0 }} 
              animate={{ scale: 1, opacity: 1 }} 
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
            >
              <h3>Оставить отзыв о тест-драйве</h3>
              <form onSubmit={handleReviewSubmit}>
                <div className={styles.modalField}>
                  <label>Оценка</label>
                  <div style={{ display: 'flex', gap: '0.3rem', fontSize: '1.5rem', cursor: 'pointer' }}>
                    {[1, 2, 3, 4, 5].map((star) => (
                      <span 
                        key={star} 
                        style={{ color: star <= (hoverRating || reviewForm.rating) ? '#FFD700' : '#ccc' }}
                        onClick={() => setReviewForm({ ...reviewForm, rating: star })}
                        onMouseEnter={() => setHoverRating(star)}
                        onMouseLeave={() => setHoverRating(null)}
                      >
                        ★
                      </span>
                    ))}
                  </div>
                </div>
                <div className={styles.modalField}>
                  <label>Ваш отзыв</label>
                  <textarea 
                    placeholder="Поделитесь впечатлениями о поездке..." 
                    value={reviewForm.comment}
                    onChange={(e) => setReviewForm({ ...reviewForm, comment: e.target.value })}
                    className={styles.modalTextarea}
                    rows="4"
                    required
                  />
                </div>
                <div className={styles.modalActions}>
                  <button type="button" className={styles.cancelBtn} onClick={() => { setShowReviewModal(false); setActiveReviewTd(null); }}>
                    Отмена
                  </button>
                  <button type="submit" className={styles.submitBtn}>
                    Отправить отзыв
                  </button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Модальное окно просмотра ответов и комментариев менеджера */}
      <AnimatePresence>
        {showCommentModal && (
          <motion.div 
            className={styles.modalOverlay} 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }} 
            onClick={() => setShowCommentModal(false)}
          >
            <motion.div 
              className={styles.commentModalCard} 
              initial={{ scale: 0.9, opacity: 0 }} 
              animate={{ scale: 1, opacity: 1 }} 
              exit={{ scale: 0.9, opacity: 0 }} 
              onClick={e => e.stopPropagation()}
            >
              <div className={styles.commentModalHeader}>
                <h4>{commentModalTitle}</h4>
                <button onClick={() => setShowCommentModal(false)} className={styles.closeCommentBtn}>✕</button>
              </div>
              <div className={styles.commentModalBody}>
                <p>{activeComment}</p>
              </div>
              <div className={styles.commentModalActions}>
                <button className={styles.submitBtn} onClick={() => setShowCommentModal(false)}>
                  Понятно
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

export default UserDashboard;
